Translate("frFR", "scarlet-monastery", {
	title = "Monastère écarlate",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Monastère écarlate s'élève sur les hauteurs du nord-est des {link:tirisfal-glades}Clairières de Tirisfal{/link}, une grande demeure de pierre grise derrière de hauts murs. Ce fut jadis un lieu d'étude et de prière, où le clergé de {link:lordaeron}Lordaeron{/link} gardait ses livres et formait les jeunes paladins aux voies de la {link:holy-light}Lumière sacrée{/link}. C'est aujourd'hui la forteresse et le cœur battant de la {link:scarlet-crusade}Croisade écarlate{/link}. Ses cloches sonnent toujours. Ses salles sont pleines de croisés vêtus de rouge, et nul n'y entre sans le tabard de la Croisade s'il veut y être bien reçu.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne rapporte l'année de la fondation du Monastère. Avant la peste, il comptait parmi les sièges les plus fiers de la foi de {link:lordaeron}Lordaeron{/link}, un bastion du savoir caché dans les clairières. Les érudits venaient à sa bibliothèque. Les paladins en formation étudiaient dans ses salles. Quand la {link:third-war}Troisième Guerre{/link} amena le {link:scourge}Fléau{/link} et la {link:fall-of-lordaeron}chute de Lordaeron{/link}, les fanatiques de la Croisade s'emparèrent du Monastère et en firent une place forte. Ils croient que tout étranger peut porter la peste, et ils traitent toute race autre que la leur en ennemie.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Le Monastère est le principal bastion de la Croisade à {link:tirisfal-glades}Tirisfal{/link}. D'ici, elle envoie ses patrouilles et ses messagers vers les tours des clairières, et elle fait la guerre aux {link:forsaken}Réprouvés{/link} aux portes mêmes de leur capitale. Le commandant écarlate {link:scarlet-commander-mograine}Mograine{/link} dirige sa garnison. Son véritable maître est la grande inquisitrice {link:high-inquisitor-whitemane}Whitemane{/link}, une prêtresse qui, dit-on, relève les morts pour qu'ils combattent de nouveau à son commandement. À {link:undercity}Undercity{/link}, {link:varimathras}Varimathras{/link} veut la mort de Whitemane et de ses principaux lieutenants. À {link:southshore}Southshore{/link}, {link:raleigh-the-devout}Raleigh the Devout{/link}, qui servit jadis ici, veut la même chose. Les érudits de la {link:horde}Horde{/link} comme de l'{link:alliance}Alliance{/link} veulent ce qui reste dans la bibliothèque. Les Réprouvés veulent des cœurs, des livres et la vengeance.]=],
		},
		{
			title = "Dans le Monastère",
			text = [=[• {b}Le cimetière.{/b} Derrière le Monastère s'étend son cimetière. Les interrogateurs de la Croisade travaillent dans ses cryptes, et les morts sans repos errent parmi les tombes.
• {b}La bibliothèque.{/b} La grande bibliothèque renferme encore les anciens livres du Monastère, gardés par le maître-chien et l'arcaniste de la Croisade.
• {b}L'armurerie.{/b} Ici, la Croisade entraîne ses recrues et arme ses guerriers, sous l'œil de son champion.
• {b}La cathédrale.{/b} Au cœur du Monastère, {link:scarlet-commander-mograine}Mograine{/link} et {link:high-inquisitor-whitemane}Whitemane{/link} tiennent le sanctuaire de la Croisade.]=],
		},
	},
})

Translate("frFR", "scarlet-monastery-graveyard", {
	title = "Cimetière du Monastère écarlate",
	sections = {
		{
			title = "Résumé",
			text = [=[Le cimetière du Monastère s'étend parmi des tombes et des cryptes brisées. La Croisade n'y laisse pas ses morts reposer en paix. Ses interrogateurs ont fait des cryptes un lieu de tourment, où les prisonniers réprouvés souffrent jusqu'à ce qu'ils disent ce qu'ils savent, ou jusqu'à ce qu'il ne reste plus rien d'eux. Les morts du cimetière sont eux aussi sans repos. Des esprits tourmentés et des fantômes errent entre les mausolées, et un mage de sang mort-vivant réclame des âmes dans la crypte la plus profonde. Certains morts sont anciens. D'autres, comme le champion déchu qui y rôde, portèrent jadis les couleurs de la Croisade elle-même.]=],
		},
	},
})

Translate("frFR", "scarlet-monastery-library", {
	title = "Bibliothèque du Monastère écarlate",
	sections = {
		{
			title = "Résumé",
			text = [=[La bibliothèque est ce qui reste de l'ancien savoir du Monastère. Ses rayonnages renferment des ouvrages d'histoire, de savoir et de rituels rassemblés au fil de longues années, et certains sont d'une rareté inestimable : une mythologie des titans, un compendium des déchus, un traité sur les premiers jours de la menace des morts-vivants, un livre de rituels de mage. La Croisade se sert de ces livres pour former ses paladins contre les morts. Elle ne laisse personne d'autre les lire. Les pisteurs du maître-chien parcourent les cloîtres extérieurs, et l'arcaniste garde la salle intérieure.]=],
		},
	},
})

Translate("frFR", "scarlet-monastery-armory", {
	title = "Armurerie du Monastère écarlate",
	sections = {
		{
			title = "Résumé",
			text = [=[L'armurerie est l'endroit où la Croisade forge ses soldats. Ses terrains d'entraînement résonnent d'exercices. Des myrmidons, des défenseurs et des centurions gardent ses salles, et les armes de la Croisade sont entreposées dans ses chambres fortes. {link:herod}Herod{/link}, le champion écarlate, règne ici, et les armes de la Croisade sont à lui de donner. C'est le meilleur guerrier du Monastère, et une foule de jeunes recrues l'observe en attendant d'être appelée. C'est ici que la Croisade change des fermiers endeuillés et des orphelins en fanatiques vêtus de rouge.]=],
		},
	},
})

Translate("frFR", "scarlet-monastery-cathedral", {
	title = "Cathédrale du Monastère écarlate",
	sections = {
		{
			title = "Résumé",
			text = [=[La cathédrale est le sanctuaire du Monastère et le siège de ses maîtres. Ses jardins et sa cour grouillent de moines, de chapelains, d'abbés et de champions de la Croisade. Au-delà, dans la grande chapelle, le commandant écarlate {link:scarlet-commander-mograine}Mograine{/link} attend devant l'autel, et la grande inquisitrice {link:high-inquisitor-whitemane}Whitemane{/link} attend derrière lui. Ceux qui atteignent la chapelle en ressortent rarement. Plus loin encore, dans une salle que peu voient jamais, demeure un second grand inquisiteur, {link:high-inquisitor-fairbanks}Fairbanks{/link}. Qui tient la cathédrale tient le Monastère.]=],
		},
	},
})

Translate("frFR", "high-inquisitor-whitemane", {
	title = "Grande inquisitrice Whitemane",
	subtitle = "Véritable maître du Monastère",
	found = "La grande chapelle de la Cathédrale du Monastère écarlate",
	hint = [=[Apprenez à la connaître par les ennemis de la Croisade, ou cherchez-la dans la chapelle de la cathédrale.]=],
	allegiance = "Croisade écarlate",
	aliases = { "Whitemane" },
	sections = {
		{
			title = "Résumé",
			text = [=[La grande inquisitrice Whitemane est le véritable maître du {link:scarlet-monastery}Monastère écarlate{/link}. {link:scarlet-commander-mograine}Mograine{/link} dirige ses soldats, mais c'est à Whitemane qu'obéit la Croisade à {link:tirisfal-glades}Tirisfal{/link}. C'est une prêtresse d'une puissance redoutable. Elle soigne ses champions, les protège, plonge ses ennemis dans un profond sommeil et plie leur esprit à sa volonté. Le plus redouté de tous est son pouvoir sur la mort elle-même. Quand ses guerriers tombent, elle les relève pour qu'ils combattent de nouveau en son nom.]=],
		},
		{
			title = "Importance",
			text = [=[Whitemane est à la tête de l'inquisition de la Croisade à {link:tirisfal-glades}Tirisfal{/link}. Ses inquisiteurs cherchent la peste chez tous ceux qu'ils rencontrent, et ils la trouvent partout où ils regardent. Sous son règne, le Monastère devint un lieu où des hommes et des femmes innocents furent torturés parce qu'ils ne portaient pas le tabard de la Croisade. Pour les {link:forsaken}Réprouvés{/link}, elle est le principal ennemi à leur porte. Pour ceux des vivants qui servirent jadis la Croisade, elle est la preuve de sa chute.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle tient le Monastère pour la {link:scarlet-crusade}Croisade écarlate{/link}, avec {link:scarlet-commander-mograine}Mograine{/link} à ses côtés.
• Elle dirige une inquisition qui traite tout étranger en porteur de la peste.
• Elle fait appel à la Lumière pour châtier ses ennemis, pour soigner et pour protéger.
• Elle relève d'entre les morts son champion tombé pour qu'il combatte de nouveau.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique de ces jours ne rapporte la vie de Whitemane avant la Croisade, l'année où elle devint grande inquisitrice, ni où elle apprit son pouvoir sur les morts.]=],
		},
	},
	chapters = {
		{
			title = "L'épine la plus acérée",
			hint = [=[Écoutez ce que le seigneur de l'effroi d'Undercity veut voir accompli à Tirisfal.]=],
			text = [=[Pendant que {link:sylvanas-windrunner}la Dame noire{/link} surveillait le roi-liche dans le nord, {link:varimathras}Varimathras{/link} se tourna vers les ennemis les plus proches. Il appela la Croisade l'épine la plus acérée dans le flanc des {link:forsaken}Réprouvés{/link}, et des fourmis rouges qui envahissent les clairières. Il voulait la mort de Whitemane, une fois pour toutes, et avec elle celle de chacun de ses principaux lieutenants.]=],
		},
		{
			title = "Le régime dément",
			hint = "Écoutez le récit du croisé qui quitta le Monastère.",
			text = [=[{link:raleigh-the-devout}Raleigh{/link} the Devout servit jadis au Monastère avec fierté. Il vit ses chefs perdre prise sur la vérité. Il vit des innocents torturés au nom de la pureté. Il partit, et il en vint à croire que la Croisade ne guérirait pas tant que ceux qui la menaient vivraient. Whitemane fut le premier nom qu'il donna. Ce n'est qu'une fois qu'elle serait tombée, disait-il, que la vraie cause pourrait de nouveau s'embraser.]=],
		},
		{
			title = "Relève-toi",
			hint = "Affrontez la grande inquisitrice dans sa chapelle.",
			text = [=[Quand {link:scarlet-commander-mograine}Mograine{/link} tombe devant son autel, Whitemane surgit avec fureur, et elle crie à la trahison. Elle endort ses ennemis. Puis elle s'agenouille au-dessus de son commandant et invoque la Lumière, et Mograine se relève pour combattre de nouveau à ses côtés.]=],
		},
	},
	mentions = {
		{ text = "Dans le {link:scarlet-monastery}Monastère écarlate{/link}" },
		{ text = "Au nom de la Lumière" },
	},
	bonds = {
		{ id = "scarlet-commander-mograine", name = "Commandant écarlate Mograine", note = "son commandant" },
		{ id = "high-inquisitor-fairbanks", name = "Grand inquisiteur Fairbanks", note = "partage son rang" },
		{ id = "varimathras", name = "Varimathras", note = "veut sa mort" },
		{ id = "raleigh-the-devout", name = "Raleigh the Devout", note = "servit jadis sous ses ordres" },
	},
})

Translate("frFR", "scarlet-commander-mograine", {
	title = "Commandant écarlate Mograine",
	subtitle = "Commandant du Monastère",
	found = "Devant l'autel de la Cathédrale du Monastère écarlate",
	hint = [=[Apprenez à le connaître par les ennemis de la Croisade, ou affrontez-le devant l'autel de la cathédrale.]=],
	allegiance = "Croisade écarlate",
	aliases = { "Mograine" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le commandant écarlate Mograine dirige la garnison du {link:scarlet-monastery}Monastère écarlate{/link}, une grande armée de guerriers dévoués à la Croisade au-delà de toute raison. C'est un paladin de la {link:holy-light}Lumière sacrée{/link}, vêtu de plaques et farouche au combat. Il se tient devant l'autel de la cathédrale entouré de ses soldats, et il accueille chaque étranger comme un infidèle à purifier.]=],
		},
		{
			title = "Importance",
			text = [=[Mograine est l'épée du Monastère, comme {link:high-inquisitor-whitemane}Whitemane{/link} en est la volonté. Les moines, les abbés et les champions de la cathédrale sont à lui, tout comme l'armée qui en tient les portes. Ses soldats ne sont pas des mercenaires. Ce sont des fanatiques qui croient, comme lui, que la peste se cache en chaque étranger, et ils mourront plutôt que de céder une seule salle. Il combat avec toute la force d'un chevalier de la Lumière, cette même Lumière que les paladins de {link:lordaeron}Lordaeron{/link} portaient jadis contre le {link:scourge}Fléau{/link}. Cette force sert désormais un ordre qui torture les innocents. Les ennemis de la Croisade, vivants comme morts, le nomment parmi les premiers qui doivent tomber. Pour les {link:forsaken}Réprouvés{/link}, c'est un fanatique à abattre. Pour {link:raleigh-the-devout}Raleigh{/link} the Devout, qui servit jadis sous ses ordres, il est l'un des hommes qui égarèrent la Croisade.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il commande la garnison du {link:scarlet-monastery}Monastère écarlate{/link}.
• Il combat entouré de l'aura de vindicte, et il frappe en croisé de la Lumière.
• Quand il est proche de la mort, il peut invoquer la Lumière pour se guérir de toutes ses blessures.
• Il combat aux côtés de {link:high-inquisitor-whitemane}Whitemane{/link}, qui peut le relever quand il tombe.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique de ces jours ne rapporte le prénom de Mograine, ses actes avant la Croisade, ni comment il en vint à commander le Monastère.]=],
		},
	},
	chapters = {
		{
			title = "Ses principaux lieutenants",
			hint = [=[Écoutez ce que le seigneur de l'effroi d'Undercity veut voir accompli à Tirisfal.]=],
			text = [=[{link:varimathras}Varimathras{/link} ne voulait pas seulement {link:high-inquisitor-whitemane}Whitemane{/link}. Il voulait aussi la disparition des chefs qui l'entouraient, et il nomma Mograine le premier d'entre eux : un fanatique à abattre dans son propre sanctuaire.]=],
		},
		{
			title = "La chute du commandant",
			hint = "Écoutez le récit du croisé qui quitta le Monastère.",
			text = [=[Pour {link:raleigh-the-devout}Raleigh{/link} the Devout, Mograine était l'un des plus hauts dignitaires d'un régime devenu fou. Tant que de tels hommes tiendraient le Monastère, disait-il, quiconque croiserait le chemin de la Croisade serait en péril.]=],
		},
		{
			title = "Devant l'autel",
			hint = [=[Affrontez le commandant dans la grande chapelle de la cathédrale.]=],
			text = [=[Mograine reçoit les intrus à l'autel et les traite d'infidèles. Quand il tombe, la grande inquisitrice vient le venger. Elle ne le laisse pas rester mort. Relevé de sa main, il se redresse et retourne à ses côtés.]=],
		},
	},
	mentions = {
		{ text = "Dans le {link:scarlet-monastery}Monastère écarlate{/link}" },
		{ text = "Au nom de la Lumière" },
	},
	bonds = {
		{ id = "high-inquisitor-whitemane", name = "Grande inquisitrice Whitemane", note = "sa dame" },
		{ id = "herod", name = "Herod", note = "champion du Monastère" },
		{ id = "varimathras", name = "Varimathras", note = "veut sa mort" },
		{ id = "raleigh-the-devout", name = "Raleigh the Devout", note = "veut sa mort" },
	},
})

Translate("frFR", "herod", {
	title = "Herod",
	subtitle = "Le champion écarlate",
	found = "L'Armurerie du Monastère écarlate",
	hint = [=[Cherchez le champion de la Croisade dans l'armurerie du Monastère.]=],
	allegiance = "Croisade écarlate",
	sections = {
		{
			title = "Résumé",
			text = [=[Herod est le champion écarlate, le plus puissant guerrier du {link:scarlet-monastery}Monastère écarlate{/link}. Il règne sur son armurerie, où la Croisade entraîne et arme ses soldats. C'est un géant en armure de plaques qui combat avec une grande hache. Il tournoie parmi ses ennemis dans une tempête de lames, les charge, et ne devient que plus sauvage à mesure qu'il saigne.]=],
		},
		{
			title = "Importance",
			text = [=[Herod est le modèle de guerrier que prône la Croisade. Les recrues de l'armurerie s'exercent sous ses yeux et attendent sa parole. Les myrmidons, les défenseurs et les centurions qui gardent les salles de l'armurerie lui obéissent, et c'est lui qui décide lesquelles des jeunes recrues sont prêtes à prendre les armes de la Croisade. Il est l'un des quatre chefs du Monastère dont {link:varimathras}Varimathras{/link} et {link:raleigh-the-devout}Raleigh the Devout{/link} réclament tous deux la mort. Il aspire à un adversaire digne de lui, et il invoque la Lumière pour lui donner la force même tandis qu'il abat ses ennemis.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il commande l'armurerie du Monastère et ses terrains d'entraînement.
• Il tourbillonne parmi ses ennemis, les fend et fond sur eux.
• Dans sa fureur, il devient plus fort à mesure que ses blessures s'aggravent.
• Quand il tombe, les recrues de l'armurerie se ruent pour le venger.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique de ces jours ne rapporte d'où venait Herod ni comment il gagna son titre.]=],
		},
	},
	chapters = {
		{
			title = "Le défi du champion",
			hint = "Affrontez le champion dans l'armurerie du Monastère.",
			text = [=[Herod accueille les intrus avec joie, car il attend depuis longtemps un vrai défi. Il est heureux de combattre. Quand il meurt enfin, ses recrues affluent dans la salle, jeunes et inexpérimentées, pour achever ce que leur champion n'a pu accomplir.]=],
		},
	},
	mentions = {
		{ text = "Dans le {link:scarlet-monastery}Monastère écarlate{/link}" },
		{ text = "Au nom de la Lumière" },
	},
	bonds = {
		{ id = "scarlet-commander-mograine", name = "Commandant écarlate Mograine", note = "son commandant" },
		{ id = "high-inquisitor-whitemane", name = "Grande inquisitrice Whitemane", note = "maître du Monastère" },
	},
})

Translate("frFR", "high-inquisitor-fairbanks", {
	title = "Grand inquisiteur Fairbanks",
	subtitle = "L'inquisiteur caché",
	found = "Une salle cachée au-delà de la chapelle de la cathédrale",
	hint = [=[Cherchez au-delà de l'autel de la cathédrale un second inquisiteur.]=],
	allegiance = "Croisade écarlate",
	aliases = { "Fairbanks" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le grand inquisiteur Fairbanks demeure dans la {link:scarlet-monastery-cathedral}Cathédrale du Monastère écarlate{/link}, dans une salle au-delà de la chapelle où {link:high-inquisitor-whitemane}Whitemane{/link} tient sa cour. Peu savent qu'il est là. Il porte le même rang que Whitemane, le titre de grand inquisiteur, et pourtant c'est elle qui gouverne le Monastère, et lui qu'on tient à l'écart des regards. Il est pâle comme un cadavre, et sa voix est la voix creuse des morts.]=],
		},
		{
			title = "Importance",
			text = [=[Fairbanks est une énigme au cœur de la Croisade. Au Monastère, seule {link:high-inquisitor-whitemane}Whitemane{/link} porte le même titre. La Croisade brûle les morts-vivants partout où elle les trouve, et pourtant un grand inquisiteur à l'allure de mort vit dans son propre sanctuaire. C'est néanmoins un prêtre de grand talent. Il se protège et se soigne, jette une malédiction de sang sur ses ennemis, les plonge dans le sommeil et les fait fuir de terreur.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il détient le rang de grand inquisiteur de la Croisade.
• Il se tient dans une salle à part, au-delà de l'autel de la cathédrale.
• Il maudit, terrifie et endort ses ennemis, et il soigne ses propres blessures.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique de ces jours ne rapporte qui était Fairbanks, pourquoi il partage le rang de {link:high-inquisitor-whitemane}Whitemane{/link}, ni pourquoi il est tenu à l'écart du reste du Monastère.]=],
		},
	},
	chapters = {
		{
			title = "La salle au-delà",
			hint = "Trouvez l'inquisiteur qui attend au-delà de la chapelle.",
			text = [=[Passé l'autel où tombèrent {link:scarlet-commander-mograine}Mograine{/link} et {link:high-inquisitor-whitemane}Whitemane{/link} se trouve une porte, et derrière la porte attend Fairbanks. Il combat seul, sans gardes et sans l'armée qui sert Mograine. Ce qu'il sait de la Croisade, et pourquoi elle le tient caché, il le garde pour lui. Ceux qui quittent sa salle n'en emportent que davantage de questions.]=],
		},
	},
	bonds = {
		{ id = "high-inquisitor-whitemane", name = "Grande inquisitrice Whitemane", note = "partage son rang" },
	},
})

Translate("frFR", "arcanist-doan", {
	title = "Arcaniste Doan",
	subtitle = "Gardien de la bibliothèque",
	found = "La salle intérieure de la Bibliothèque du Monastère écarlate",
	hint = [=[Cherchez l'arcaniste qui garde la salle intérieure de la bibliothèque du Monastère.]=],
	allegiance = "Croisade écarlate",
	aliases = { "Doan" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'arcaniste Doan est le mage qui garde la bibliothèque du {link:scarlet-monastery}Monastère écarlate{/link}. Il tient ses livres pour de saints mystères qu'aucun étranger ne doit profaner. Il brûle les intrus dans ce qu'il appelle un feu vertueux. Il les réduit au silence, les change en bêtes, et quand ils le pressent de trop près, il s'enveloppe d'une bulle de puissance arcanique et la fait éclater en une grande déflagration.]=],
		},
		{
			title = "Importance",
			text = [=[Doan se dresse entre les ennemis de la Croisade et son savoir. Les livres que cherchent les érudits de {link:thunder-bluff}Thunder Bluff{/link}, d'{link:ironforge}Ironforge{/link} et d'{link:undercity}Undercity{/link} se trouvent tous derrière lui. {link:sage-truthseeker}Sage Truthseeker{/link} veut le Compendium des Déchus, et un bibliothécaire d'Ironforge veut la Mythologie des Titans. Un historien d'Undercity veut le traité dont la Croisade se sert pour former ses paladins contre les morts.]=],
		},
	},
	mentions = {
