Translate("frFR", "bloodmage-thalnos", {
	title = "Mage de sang Thalnos",
	subtitle = "Le mort courroucé",
	found = "Les cryptes du Cimetière du Monastère écarlate",
	hint = [=[Cherchez le mage mort qui hante les cryptes du cimetière du Monastère.]=],
	allegiance = "Les morts sans repos",
	aliases = { "Thalnos" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le mage de sang Thalnos est un sorcier mort qui hante les cryptes du {link:scarlet-monastery-graveyard}Cimetière du Monastère écarlate{/link}. Il ne sert ni la Croisade ni les {link:forsaken}Réprouvés{/link}. Il a faim d'âmes et de vengeance, et il crie qu'il n'y a pas de repos pour les morts courroucés. Il projette le feu et l'ombre sur les vivants, et des flammes jaillissent de lui quand ils s'approchent. Les tortionnaires de la Croisade ne travaillent qu'à quelques salles de là. S'ils savent ce qui gît dans la crypte la plus profonde, nul ne l'a dit.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique de ces jours ne rapporte qui était Thalnos de son vivant, comment il mourut, ni de qui il entend se venger.]=],
		},
	},
	bonds = {
		{ id = "interrogator-vishas", name = "Interrogateur Vishas", note = "travaille dans le même cimetière" },
	},
})

Translate("frFR", "interrogator-vishas", {
	title = "Interrogateur Vishas",
	subtitle = "Tortionnaire de la Croisade",
	found = "La salle de torture du Cimetière du Monastère écarlate",
	hint = [=[Cherchez l'interrogateur de la Croisade dans les cryptes du cimetière.]=],
	allegiance = "Croisade écarlate",
	aliases = { "Vishas" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'interrogateur Vishas torture les prisonniers de la Croisade dans les cryptes du {link:scarlet-monastery-graveyard}Cimetière du Monastère écarlate{/link}. Il veut tous les secrets, et il les arrache par le feu et la douleur. Il est fier de son travail, et fier de sa femme, Nancy, qui vit au bord du lac Lordamere. Il lui offrit une alliance qu'il avait prise à l'une de ses victimes.]=],
		},
	},
	chapters = {
		{
			title = "L'anneau volé",
			hint = [=[Écoutez le dernier souhait d'un Réprouvé mourant dans le cimetière.]=],
			text = [=[{link:vorrel-sengutz}Vorrel Sengutz{/link} avait enduré des semaines de tourments aux mains de Vishas. Quand l'interrogateur tomba, Vorrel s'en réjouit. Il lui restait un souhait : que la femme de Vishas paie pour ce que son mari avait fait, et que son anneau retourne à sa propre femme à {link:tarren-mill}Moulin-de-Tarren{/link}.]=],
		},
	},
	mentions = {
		{ text = "La vengeance de {link:vorrel-sengutz}Vorrel{/link}" },
	},
	bonds = {
		{ id = "vorrel-sengutz", name = "Vorrel Sengutz", note = "sa victime" },
	},
})

Translate("frFR", "vorrel-sengutz", {
	title = "Vorrel Sengutz",
	subtitle = "Prisonnier du cimetière",
	found = "Les cryptes du Cimetière du Monastère écarlate",
	hint = [=[Cherchez un Réprouvé brisé parmi les prisonniers de la Croisade dans le cimetière.]=],
	allegiance = "Réprouvés",
	aliases = { "Vorrel" },
	sections = {
		{
			title = "Résumé",
			text = [=[Vorrel Sengutz est l'un des {link:forsaken}Réprouvés{/link}, un mort qui s'éveilla maître de sa propre volonté et servit {link:sylvanas-windrunner}la Dame noire{/link}. La Croisade le captura. L'interrogateur {link:interrogator-vishas}Vishas{/link} le tortura pendant des semaines et lui vola son alliance. Aujourd'hui, Vorrel gît brisé dans le cimetière. Il sait que son temps en ce monde touche à sa fin. Il ne veut que la vengeance, et il veut que son anneau soit rendu à sa femme, Monika, à {link:tarren-mill}Moulin-de-Tarren{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Son dernier souhait",
			hint = "Écoutez le souhait du prisonnier mourant.",
			text = [=[{link:interrogator-vishas}Vishas{/link} s'était vanté de sa femme, Nancy, qui vivait au bord du lac Lordamere. Vorrel demanda qu'on la retrouve et qu'on la tue, et que son anneau soit porté à Monika. Quand Vishas tomba, Vorrel dit que le tortionnaire avait eu ce qu'il méritait.]=],
		},
	},
	mentions = {
		{ text = "La vengeance de Vorrel" },
	},
	bonds = {
		{ id = "interrogator-vishas", name = "Interrogateur Vishas", note = "son tortionnaire" },
	},
})

Translate("frFR", "azshir-the-sleepless", {
	title = "Azshir l'Insomniaque",
	subtitle = "Errant du cimetière",
	found = "Errant dans le Cimetière du Monastère écarlate",
	hint = [=[Guettez parmi les tombes du cimetière du Monastère un esprit qui ne dort jamais.]=],
	allegiance = "Les morts sans repos",
	aliases = { "Azshir" },
	sections = {
		{
			title = "Résumé",
			text = [=[Azshir l'Insomniaque est un esprit ténébreux qui erre dans le {link:scarlet-monastery-graveyard}Cimetière du Monastère écarlate{/link}. Il ne reste pas en un seul lieu, et il ne se repose pas. Il draine l'âme des vivants, les frappe de terreur et appelle les morts des tombes à combattre pour lui. On le voit rarement. Il partage le cimetière avec les autres morts sans repos, à quelques salles seulement de l'endroit où les tortionnaires de la Croisade exercent leur métier. Son nom est presque tout ce que les vivants savent de lui.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique de ces jours ne rapporte ce qu'était Azshir avant sa mort, ni pourquoi il ne peut dormir.]=],
		},
	},
	bonds = {
		{ id = "bloodmage-thalnos", name = "Mage de sang Thalnos", note = "un autre des morts courroucés" },
	},
})
